```{.r .cell-code  code-fold="true"}
n1 <- length(group_a)
n2 <- length(group_b)
T_a <- sum(rank_a)
T_b <- sum(rank_b)
U_a <- n1 * n2 + 0.5 * n1 * (n1 + 1) - T_a
U_b <- n1 * n2 + 0.5 * n2 * (n2 + 1) - T_b
U <- min(U_a, U_b)
sigma <- sqrt(n1 * n2 * (n1 + n2 + 1) / 12)

tibble(
  Group = c("A", "B"),
  N = c(n1, n2),
  `Sum of Ranks` = c(T_a, T_b),
  U = c(U_a, U_b),
  `Std. Dev of U` = c(sigma, sigma)
) |>
  knitr::kable(digits = 3, align = "lrrrr")
```

