  DF = c(anova_2way$Df[1], anova_2way$Df[2], anova_2way$Df[3], anova_2way$Df[4], sum(anova_2way$Df)),
  MS = c(anova_2way$`Mean Sq`[1], anova_2way$`Mean Sq`[2], anova_2way$`Mean Sq`[3], anova_2way$`Mean Sq`[4], NA),
  F = c(anova_2way$`F value`[1], anova_2way$`F value`[2], anova_2way$`F value`[3], NA, NA),
  `p-value` = c(anova_2way$`Pr(>F)`[1], anova_2way$`Pr(>F)`[2], anova_2way$`Pr(>F)`[3], NA, NA)
) |>
  mutate(across(c(MS, F, `p-value`), ~ ifelse(is.na(.x), "", as.character(round(.x, 4))))) |>
